#include <bits/stdc++.h>
using namespace std;const int N=50005,M=200005;int h[N],to[M],nx[M],q[N],e;unsigned long long w[M],d[N],b[64];bool v[N];void I(unsigned long long x){for(int i=63;i>=0;i--)if(x>>i&1){if(b[i])x^=b[i];else{b[i]=x;return;}}}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m;cin>>n>>m;while(m--){int x,y;unsigned long long z;cin>>x>>y>>z;to[++e]=y;w[e]=z;nx[e]=h[x];h[x]=e;to[++e]=x;w[e]=z;nx[e]=h[y];h[y]=e;}int l=0,r=1;q[0]=1;v[1]=1;while(l<r){int x=q[l++];for(int i=h[x];i;i=nx[i])if(!v[to[i]])v[to[i]]=1,d[to[i]]=d[x]^w[i],q[r++]=to[i];else I(d[x]^d[to[i]]^w[i]);}unsigned long long s=d[n];for(int i=63;i>=0;i--)s=max(s,s^b[i]);cout<<s<<'\n';}
